1	// Meeting-room booking server: JSON API, static page, one JSON data file.
2	// Node.js built-ins only.
3	import { createServer } from 'node:http';
4	import { readFile, writeFile } from 'node:fs/promises';
5	import { dirname, join, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const DEFAULT_DATA_FILE = 'bookings.json';
12	const MAX_BODY_BYTES = 10000;
13	const JSON_TYPE = 'application/json; charset=utf-8';
14	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
15	const BOOKINGS_PREFIX = '/api/bookings/';
16	const PUBLIC_DIR = join(dirname(fileURLToPath(import.meta.url)), 'public');
17	const STATIC_FILES = Object.freeze({
18	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
19	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
20	});
21	
22	const MSG = Object.freeze({
23	  internal: 'internal error',
24	  notFound: 'not found',
25	  method: 'method not allowed',
26	  bookingNotFound: 'booking not found',
27	  contentType: 'content type must be application/json',
28	  tooLarge: 'body too large',
29	  notObject: 'body must be a JSON object',
30	  room: 'room must be one of Aurora, Borealis, Cosmos',
31	  title: 'title must be 1 to 80 characters',
32	  date: 'date must be a valid YYYY-MM-DD date',
33	  start: 'start must be HH:MM',
34	  end: 'end must be HH:MM',
35	  order: 'end must be after start',
36	});
37	
38	// ---------- validation helpers ----------
39	
40	const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
41	
42	function isValidDate(value) {
43	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
44	  const year = Number(value.slice(0, 4));
45	  const month = Number(value.slice(5, 7));
46	  const day = Number(value.slice(8, 10));
47	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
48	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
49	  return day <= daysInMonth[month - 1];
50	}
51	
52	function isValidTime(value) {
53	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
54	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
55	}
56	
57	/** A title is valid when, trimmed, it holds 1 to 80 UTF-16 code units. */
58	function isValidTitle(value) {
59	  if (typeof value !== 'string') return false;
60	  const length = value.trim().length;
61	  return length >= 1 && length <= 80;
62	}
63	
64	const overlaps = (a, b) =>
65	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
66	
67	const compareText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
68	
69	/** Returns an error message for the first failing field rule (4-9), or null. */
70	function fieldError(body) {
71	  if (!ROOMS.includes(body.room)) return MSG.room;
72	  if (!isValidTitle(body.title)) return MSG.title;
73	  if (!isValidDate(body.date)) return MSG.date;
74	  if (!isValidTime(body.start)) return MSG.start;
75	  if (!isValidTime(body.end)) return MSG.end;
76	  if (body.end <= body.start) return MSG.order;
77	  return null;
78	}
79	
80	// ---------- data file ----------
81	
82	function isStoredBooking(b, nextId) {
83	  if (!isPlainObject(b)) return false;
84	  const keys = Object.keys(b);
85	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => Object.hasOwn(b, k))) {
86	    return false;
87	  }
88	  if (!Number.isSafeInteger(b.id) || b.id < 1 || b.id >= nextId) return false;
89	  if (!ROOMS.includes(b.room) || !isValidDate(b.date)) return false;
90	  if (!isValidTitle(b.title) || b.title !== b.title.trim()) return false;
91	  return isValidTime(b.start) && isValidTime(b.end) && b.start < b.end;
92	}
93	
94	/** Strict check that `data` is exactly what this server writes. */
95	function isValidStore(data) {
96	  if (!isPlainObject(data)) return false;
97	  const keys = Object.keys(data);
98	  if (keys.length !== 2 || !Object.hasOwn(data, 'nextId') || !Object.hasOwn(data, 'bookings')) {
99	    return false;
100	  }
101	  const { nextId, bookings } = data;
102	  // nextId must stay safe after one more booking, so a saved file always reloads.
103	  if (!Number.isSafeInteger(nextId + 1) || nextId < 1 || !Array.isArray(bookings)) return false;
104	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return false;
105	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
106	  return bookings.every((b, i) => bookings.slice(i + 1).every((o) => !overlaps(b, o)));
107	}
108	
109	const emptyStore = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
110	
111	/** Resolves to the loaded store, or null when the file exists but is unusable. */
112	async function loadStore(path) {
113	  let text;
114	  try {
115	    text = await readFile(path, 'utf8');
116	  } catch (err) {
117	    if (err && err.code === 'ENOENT') return emptyStore();
118	    return null;
119	  }
120	  let data;
121	  try {
122	    data = JSON.parse(text);
123	  } catch {
124	    return null;
125	  }
126	  if (!isValidStore(data)) return null;
127	  return Object.freeze({
128	    nextId: data.nextId,
129	    bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))),
130	  });
131	}
132	
133	const saveStore = (path, store) => writeFile(path, JSON.stringify(store));
134	
135	// ---------- HTTP helpers ----------
136	
137	function sendJson(res, status, payload) {
138	  const body = JSON.stringify(payload);
139	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
140	  res.end(body);
141	}
142	
143	const sendError = (res, status, message) => sendJson(res, status, { error: message });
144	
145	function sendNoContent(res) {
146	  res.writeHead(204);
147	  res.end();
148	}
149	
150	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes, counts all of them. */
151	function readBody(req) {
152	  return new Promise((resolveBody, rejectBody) => {
153	    const chunks = [];
154	    let size = 0;
155	    let kept = 0;
156	    req.on('data', (chunk) => {
157	      size += chunk.length;
158	      if (kept <= MAX_BODY_BYTES) {
159	        chunks.push(chunk);
160	        kept += chunk.length;
161	      }
162	    });
163	    req.on('end', () => resolveBody({ size, buffer: Buffer.concat(chunks) }));
164	    req.on('error', rejectBody);
165	    req.on('close', () => {
166	      if (!req.complete) rejectBody(new Error('request closed before its body was read'));
167	    });
168	  });
169	}
170	
171	function mediaType(header) {
172	  if (typeof header !== 'string') return null;
173	  return header
174	    .split(';')[0]
175	    .replace(/^[ \t]+|[ \t]+$/g, '')
176	    .replace(/[A-Z]/g, (c) => c.toLowerCase());
177	}
178	
179	function parseObject(buffer) {
180	  try {
181	    const value = JSON.parse(buffer.toString('utf8'));
182	    return isPlainObject(value) ? value : null;
183	  } catch {
184	    return null;
185	  }
186	}
187	
188	const compareByStart = (a, b) => compareText(a.start, b.start);
189	
190	function compareBookings(a, b) {
191	  return (
192	    compareText(a.date, b.date) ||
193	    compareByStart(a, b) ||
194	    ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room) ||
195	    a.id - b.id
196	  );
197	}
198	
199	// ---------- application ----------
200	
201	/**
202	 * Holds the in-memory store (the source of truth after startup) and runs
203	 * mutations one at a time. `commit` saves first and only then replaces the
204	 * store, so a failed save changes nothing, the next id included.
205	 */
206	function createRepository(dataPath, initialStore) {
207	  let store = initialStore;
208	  let queue = Promise.resolve();
209	  return Object.freeze({
210	    current: () => store,
211	    // The returned promise carries the task's own result or error to the
212	    // caller; the chain only needs to settle so the next task can run.
213	    serialize(task) {
214	      const run = queue.then(task);
215	      queue = run.then(
216	        () => undefined,
217	        () => undefined,
218	      );
219	      return run;
220	    },
221	    async commit(next) {
222	      await saveStore(dataPath, next);
223	      store = next;
224	    },
225	  });
226	}
227	
228	function listBookings(repo, res, query) {
229	  const params = new URLSearchParams(query);
230	  let bookings = repo.current().bookings;
231	  if (params.has('date')) {
232	    const date = params.get('date');
233	    if (!isValidDate(date)) return sendError(res, 400, MSG.date);
234	    bookings = bookings.filter((b) => b.date === date);
235	  }
236	  return sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
237	}
238	
239	/** Applies booking rules 1-9; returns the booking fields, or null after replying. */
240	function readBookingInput(req, res, body) {
241	  if (mediaType(req.headers['content-type']) !== 'application/json') {
242	    sendError(res, 415, MSG.contentType);
243	    return null;
244	  }
245	  if (body.size > MAX_BODY_BYTES) {
246	    sendError(res, 413, MSG.tooLarge);
247	    return null;
248	  }
249	  const input = parseObject(body.buffer);
250	  const invalid = input === null ? MSG.notObject : fieldError(input);
251	  if (invalid !== null) {
252	    sendError(res, 400, invalid);
253	    return null;
254	  }
255	  const { room, title, date, start, end } = input;
256	  return Object.freeze({ room, title: title.trim(), date, start, end });
257	}
258	
259	function createBooking(repo, req, res, body) {
260	  const fields = readBookingInput(req, res, body);
261	  if (fields === null) return undefined;
262	  return repo.serialize(async () => {
263	    const store = repo.current();
264	    const [clash] = store.bookings.filter((b) => overlaps(b, fields)).sort(compareByStart);
265	    if (clash) {
266	      return sendError(res, 409, `room is already booked from ${clash.start} to ${clash.end}`);
267	    }
268	    const booking = Object.freeze({ id: store.nextId, ...fields });
269	    await repo.commit(
270	      Object.freeze({
271	        nextId: store.nextId + 1,
272	        bookings: Object.freeze([...store.bookings, booking]),
273	      }),
274	    );
275	    return sendJson(res, 201, booking);
276	  });
277	}
278	
279	function deleteBooking(repo, res, idText) {
280	  return repo.serialize(async () => {
281	    const store = repo.current();
282	    const found =
283	      /^[1-9][0-9]*$/.test(idText) && store.bookings.some((b) => String(b.id) === idText);
284	    if (!found) return sendError(res, 404, MSG.bookingNotFound);
285	    await repo.commit(
286	      Object.freeze({
287	        nextId: store.nextId,
288	        bookings: Object.freeze(store.bookings.filter((b) => String(b.id) !== idText)),
289	      }),
290	    );
291	    return sendNoContent(res);
292	  });
293	}
294	
295	async function serveStatic(res, entry) {
296	  const content = await readFile(join(PUBLIC_DIR, entry.file));
297	  res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
298	  res.end(content);
299	}
300	
301	/** Splits the raw request target at the first `?`; nothing is decoded. */
302	function splitTarget(target) {
303	  const qIndex = target.indexOf('?');
304	  return qIndex === -1
305	    ? { path: target, query: '' }
306	    : { path: target.slice(0, qIndex), query: target.slice(qIndex + 1) };
307	}
308	
309	function route(repo, req, res, body) {
310	  const { path, query } = splitTarget(req.url ?? '');
311	  const { method } = req;
312	  const notAllowed = () => sendError(res, 405, MSG.method);
313	
314	  if (path === '/api/rooms') {
315	    return method === 'GET' ? sendJson(res, 200, { rooms: [...ROOMS] }) : notAllowed();
316	  }
317	  if (path === '/api/bookings') {
318	    if (method === 'GET') return listBookings(repo, res, query);
319	    if (method === 'POST') return createBooking(repo, req, res, body);
320	    return notAllowed();
321	  }
322	  if (path.startsWith(BOOKINGS_PREFIX)) {
323	    const idText = path.slice(BOOKINGS_PREFIX.length);
324	    if (idText === '' || idText.includes('/')) return sendError(res, 404, MSG.notFound);
325	    return method === 'DELETE' ? deleteBooking(repo, res, idText) : notAllowed();
326	  }
327	  if (Object.hasOwn(STATIC_FILES, path)) {
328	    return method === 'GET' ? serveStatic(res, STATIC_FILES[path]) : notAllowed();
329	  }
330	  return sendError(res, 404, MSG.notFound);
331	}
332	
333	function replyInternalError(res) {
334	  if (res.headersSent) {
335	    res.destroy();
336	    return;
337	  }
338	  sendError(res, 500, MSG.internal);
339	}
340	
341	function createHandler(repo) {
342	  return async function handle(req, res) {
343	    try {
344	      const body = await readBody(req);
345	      await route(repo, req, res, body);
346	    } catch (err) {
347	      // Any unexpected failure (save error, unreadable page, broken request)
348	      // becomes a generic 500; the cause goes to stderr, never to the client.
349	      reportServerError(err);
350	      replyInternalError(res);
351	    }
352	  };
353	}
354	
355	// ---------- startup ----------
356	
357	function fail(line) {
358	  process.stderr.write(`${line}\n`, () => process.exit(1));
359	}
360	
361	function parsePort(raw) {
362	  if (raw === undefined || raw === '') return DEFAULT_PORT;
363	  if (!/^[0-9]+$/.test(raw)) return null;
364	  const port = Number(raw);
365	  return port <= 65535 ? port : null;
366	}
367	
368	async function main() {
369	  const port = parsePort(process.env.PORT);
370	  // JSON.stringify keeps a value holding line breaks on one stderr line.
371	  if (port === null) return fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
372	
373	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
374	  const dataPath = resolve(process.cwd(), dataName);
375	  const store = await loadStore(dataPath);
376	  if (store === null) return fail(`cannot read data file ${dataName}`);
377	
378	  const handle = createHandler(createRepository(dataPath, store));
379	  const server = createServer((req, res) => {
380	    handle(req, res).catch(() => res.destroy());
381	  });
382	  const onListenError = (err) => fail(`cannot listen on ${HOST}:${port}: ${err.code ?? 'error'}`);
383	  server.once('error', onListenError);
384	  server.listen(port, HOST, () => {
385	    server.off('error', onListenError);
386	    server.on('error', reportServerError);
387	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
388	  });
389	  return undefined;
390	}
391	
392	/** A failure after startup is reported on stderr; the server keeps running. */
393	function reportServerError(err) {
394	  process.stderr.write(`server error: ${err?.code ?? err?.message ?? 'unknown'}\n`);
395	}
396	
397	main().catch(() => fail('server failed to start'));
398

