1	// Meeting-room booking server: JSON API, browser page, one JSON data file.
2	// Node.js built-ins only.
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import path from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const HOST = '127.0.0.1';
9	const DEFAULT_PORT = 3000;
10	const MAX_PORT = 65535;
11	const MAX_BODY_BYTES = 10000;
12	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
13	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
14	const JSON_TYPE = 'application/json; charset=utf-8';
15	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
16	const PAGES = Object.freeze({
17	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
18	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
19	});
20	const DELETE_ROUTE = /^\/api\/bookings\/[^/]+$/;
21	const ID_PATTERN = /^[1-9][0-9]*$/;
22	const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
23	const TIME_PATTERN = /^([0-9]{2}):([0-9]{2})$/;
24	
25	const MSG = Object.freeze({
26	  contentType: 'content type must be application/json',
27	  tooLarge: 'body too large',
28	  notObject: 'body must be a JSON object',
29	  room: 'room must be one of Aurora, Borealis, Cosmos',
30	  title: 'title must be 1 to 80 characters',
31	  date: 'date must be a valid YYYY-MM-DD date',
32	  start: 'start must be HH:MM',
33	  end: 'end must be HH:MM',
34	  order: 'end must be after start',
35	  bookingNotFound: 'booking not found',
36	  notFound: 'not found',
37	  method: 'method not allowed',
38	  internal: 'internal error',
39	});
40	
41	/** Thrown for a request that must get a specific error reply. */
42	class HttpError extends Error {
43	  constructor(status, message) {
44	    super(message);
45	    this.name = 'HttpError';
46	    this.status = status;
47	  }
48	}
49	
50	// ---------- field validation (shared by the API and the data-file check) ----------
51	
52	const isPlainObject = (value) =>
53	  typeof value === 'object' && value !== null && !Array.isArray(value);
54	
55	function isValidDate(value) {
56	  if (typeof value !== 'string') return false;
57	  const match = DATE_PATTERN.exec(value);
58	  if (!match) return false;
59	  const [year, month, day] = match.slice(1).map(Number);
60	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
61	  const febDays = year % 4 === 0 ? 29 : 28;
62	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
63	  return day <= monthDays[month - 1];
64	}
65	
66	function isValidTime(value) {
67	  if (typeof value !== 'string') return false;
68	  const match = TIME_PATTERN.exec(value);
69	  return match !== null && Number(match[1]) <= 23 && Number(match[2]) <= 59;
70	}
71	
72	function isValidTitle(value) {
73	  if (typeof value !== 'string') return false;
74	  const { length } = value.trim();
75	  return length >= 1 && length <= 80;
76	}
77	
78	const overlaps = (a, b) =>
79	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
80	
81	/** Rules 4-9 on a parsed body; returns the new booking fields or throws HttpError. */
82	function validateFields(body) {
83	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) throw new HttpError(400, MSG.room);
84	  if (!isValidTitle(body.title)) throw new HttpError(400, MSG.title);
85	  if (!isValidDate(body.date)) throw new HttpError(400, MSG.date);
86	  if (!isValidTime(body.start)) throw new HttpError(400, MSG.start);
87	  if (!isValidTime(body.end)) throw new HttpError(400, MSG.end);
88	  if (!(body.end > body.start)) throw new HttpError(400, MSG.order);
89	  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
90	}
91	
92	// ---------- data file ----------
93	
94	const emptyState = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
95	
96	function isStoredBooking(b) {
97	  if (!isPlainObject(b)) return false;
98	  const keys = Object.keys(b);
99	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
100	  return Number.isSafeInteger(b.id) && b.id >= 1 && ROOMS.includes(b.room)
101	    && isValidTitle(b.title) && b.title === b.title.trim()
102	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
103	}
104	
105	/** Strict check that `data` is exactly the layout this server writes. */
106	function isValidLayout(data) {
107	  if (!isPlainObject(data)) return false;
108	  const keys = Object.keys(data);
109	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
110	  const { nextId, bookings } = data;
111	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
112	  if (!bookings.every(isStoredBooking)) return false;
113	  const ids = new Set(bookings.map((b) => b.id));
114	  if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
115	  return !bookings.some((b, i) => bookings.slice(i + 1).some((other) => overlaps(b, other)));
116	}
117	
118	/** Reads the data file once; returns the state or null when it cannot be used. */
119	function loadState(filePath) {
120	  let text;
121	  try {
122	    text = fs.readFileSync(filePath, 'utf8');
123	  } catch (err) {
124	    return err.code === 'ENOENT' ? emptyState() : null;
125	  }
126	  let data;
127	  try {
128	    data = JSON.parse(text);
129	  } catch {
130	    return null;
131	  }
132	  if (!isValidLayout(data)) return null;
133	  return Object.freeze({ nextId: data.nextId, bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))) });
134	}
135	
136	/** Writes a temp file beside the data file, then renames it over, so a failed save leaves the old file intact. */
137	async function saveState(filePath, state) {
138	  const tempPath = `${filePath}.${process.pid}.tmp`;
139	  try {
140	    await fs.promises.writeFile(tempPath, JSON.stringify({ nextId: state.nextId, bookings: state.bookings }));
141	    await fs.promises.rename(tempPath, filePath);
142	  } catch (err) {
143	    await fs.promises.rm(tempPath, { force: true }).catch(() => {}); // best-effort cleanup; the save error below is what matters
144	    throw err;
145	  }
146	}
147	
148	// ---------- request plumbing ----------
149	
150	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts every byte received. */
151	function readBody(req) {
152	  return new Promise((resolve, reject) => {
153	    const chunks = [];
154	    let kept = 0;
155	    let total = 0;
156	    req.on('data', (chunk) => {
157	      total += chunk.length;
158	      if (kept <= MAX_BODY_BYTES) {
159	        chunks.push(chunk);
160	        kept += chunk.length;
161	      }
162	    });
163	    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
164	    req.on('error', reject);
165	    req.on('aborted', () => reject(new Error('request aborted')));
166	  });
167	}
168	
169	function send(res, status, payload) {
170	  if (status === 204) {
171	    res.writeHead(204);
172	    res.end();
173	    return;
174	  }
175	  const body = JSON.stringify(payload);
176	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
177	  res.end(body);
178	}
179	
180	const sendError = (res, status, message) => send(res, status, { error: message });
181	
182	function isJsonContentType(header) {
183	  if (typeof header !== 'string') return false;
184	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
185	  return media.toLowerCase() === 'application/json';
186	}
187	
188	function parseObjectBody(buffer) {
189	  let parsed;
190	  try {
191	    parsed = JSON.parse(buffer.toString('utf8'));
192	  } catch {
193	    throw new HttpError(400, MSG.notObject);
194	  }
195	  if (!isPlainObject(parsed)) throw new HttpError(400, MSG.notObject);
196	  return parsed;
197	}
198	
199	function compareBookings(a, b) {
200	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
201	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
202	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
203	}
204	
205	// ---------- application ----------
206	
207	function createApp(dataFile, initialState) {
208	  let state = initialState;
209	
210	  function listBookings(query) {
211	    const params = new URLSearchParams(query);
212	    let bookings = state.bookings;
213	    if (params.has('date')) {
214	      const date = params.get('date');
215	      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
216	      bookings = bookings.filter((b) => b.date === date);
217	    }
218	    return { status: 200, payload: { bookings: [...bookings].sort(compareBookings) } };
219	  }
220	
221	  async function createBooking(req, body) {
222	    if (!isJsonContentType(req.headers['content-type'])) throw new HttpError(415, MSG.contentType);
223	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
224	    const fields = validateFields(parseObjectBody(body.buffer));
225	    const clashes = state.bookings.filter((b) => overlaps(b, fields));
226	    if (clashes.length > 0) {
227	      const first = clashes.reduce((a, b) => (b.start < a.start ? b : a));
228	      throw new HttpError(409, `room is already booked from ${first.start} to ${first.end}`);
229	    }
230	    const booking = Object.freeze({ id: state.nextId, ...fields });
231	    await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
232	    return { status: 201, payload: booking };
233	  }
234	
235	  async function deleteBooking(rawId) {
236	    const id = ID_PATTERN.test(rawId) && Number.isSafeInteger(Number(rawId)) ? Number(rawId) : NaN;
237	    if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
238	    await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
239	    return { status: 204 };
240	  }
241	
242	  /** Saves the candidate state first; memory changes only when the save succeeded. */
243	  async function commit(candidate) {
244	    const next = Object.freeze({ nextId: candidate.nextId, bookings: Object.freeze(candidate.bookings) });
245	    await saveState(dataFile, next);
246	    state = next;
247	  }
248	
249	  return { listBookings, createBooking, deleteBooking };
250	}
251	
252	async function servePage(page) {
253	  const content = await fs.promises.readFile(path.join(PUBLIC_DIR, page.file));
254	  return { status: 200, page: { type: page.type, content } };
255	}
256	
257	function splitTarget(target) {
258	  const mark = target.indexOf('?');
259	  return mark === -1
260	    ? { pathname: target, query: '' }
261	    : { pathname: target.slice(0, mark), query: target.slice(mark + 1) };
262	}
263	
264	function requireMethod(method, allowed) {
265	  if (method !== allowed) throw new HttpError(405, MSG.method);
266	}
267	
268	/** Routes one request (body already read) to its result, or throws HttpError. */
269	async function route(app, req, body) {
270	  const { pathname, query } = splitTarget(req.url);
271	  const { method } = req;
272	  if (Object.hasOwn(PAGES, pathname)) {
273	    requireMethod(method, 'GET');
274	    return servePage(PAGES[pathname]);
275	  }
276	  if (pathname === '/api/rooms') {
277	    requireMethod(method, 'GET');
278	    return { status: 200, payload: { rooms: [...ROOMS] } };
279	  }
280	  if (pathname === '/api/bookings') {
281	    if (method === 'GET') return app.listBookings(query);
282	    if (method === 'POST') return app.createBooking(req, body);
283	    throw new HttpError(405, MSG.method);
284	  }
285	  if (DELETE_ROUTE.test(pathname)) {
286	    requireMethod(method, 'DELETE');
287	    return app.deleteBooking(pathname.slice('/api/bookings/'.length));
288	  }
289	  throw new HttpError(404, MSG.notFound);
290	}
291	
292	function writeResult(res, result) {
293	  if (result.page) {
294	    res.writeHead(200, { 'Content-Type': result.page.type, 'Content-Length': result.page.content.length });
295	    res.end(result.page.content);
296	    return;
297	  }
298	  send(res, result.status, result.payload);
299	}
300	
301	/** Logs an unexpected failure as one stderr line (stdout is reserved for the listening line). */
302	function logUnexpected(err) {
303	  const detail = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
304	  process.stderr.write(`request failed: ${detail.replace(/\s+/g, ' ')}\n`);
305	}
306	
307	function writeFailure(res, err) {
308	  if (!(err instanceof HttpError)) logUnexpected(err);
309	  if (res.headersSent) {
310	    res.destroy();
311	    return;
312	  }
313	  if (err instanceof HttpError) sendError(res, err.status, err.message);
314	  else sendError(res, 500, MSG.internal);
315	}
316	
317	/** Serialises request handling so concurrent requests act as if handled one at a time. */
318	function createHandler(app) {
319	  let queue = Promise.resolve();
320	  return (req, res) => {
321	    // A failed write to a vanished client must not crash the server; nothing else to do.
322	    res.on('error', () => {});
323	    readBody(req).then(
324	      (body) => {
325	        queue = queue.then(() => route(app, req, body)
326	          .then((result) => writeResult(res, result), (err) => writeFailure(res, err))
327	          .catch((err) => {
328	            logUnexpected(err);
329	            res.destroy();
330	          }));
331	      },
332	      () => res.destroy(), // client aborted before sending its body: there is no one to reply to
333	    );
334	  };
335	}
336	
337	// ---------- startup ----------
338	
339	function fail(line) {
340	  process.stderr.write(`${line}\n`);
341	  process.exit(1);
342	}
343	
344	function parsePort(raw) {
345	  if (raw === undefined || raw === '') return DEFAULT_PORT;
346	  if (!/^[0-9]+$/.test(raw)) return null;
347	  const port = Number(raw);
348	  return port <= MAX_PORT ? port : null;
349	}
350	
351	function main() {
352	  const port = parsePort(process.env.PORT);
353	  if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
354	  const dataName = process.env.DATA_FILE || 'bookings.json';
355	  const dataFile = path.resolve(process.cwd(), dataName);
356	  const state = loadState(dataFile);
357	  if (state === null) fail(`cannot read data file ${dataName}`);
358	
359	  const server = http.createServer(createHandler(createApp(dataFile, state)));
360	  server.on('clientError', (_err, socket) => {
361	    if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
362	    else socket.destroy();
363	  });
364	  const onListenError = (err) => fail(`cannot listen on port ${port}: ${err.code || 'error'}`);
365	  server.once('error', onListenError);
366	  server.listen(port, HOST, () => {
367	    server.off('error', onListenError);
368	    server.on('error', logUnexpected);
369	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
370	  });
371	}
372	
373	main();
374

