import { spawn } from 'node:child_process';
import net from 'node:net';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const sol = path.resolve(process.argv[2]);
const results = [];
const check = (name, ok, info = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : info}`);

function run(env, cwd) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [path.join(sol, 'server.mjs')], { env: { PATH: process.env.PATH, ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; if (out.includes('\n') && !p._r) { p._r = 1; resolve({ p, out, err: () => err }); } });
    p.stderr.on('data', (d) => (err += d));
    p.on('exit', (code) => { if (!p._r) { p._r = 1; resolve({ code, out, err }); } });
  });
}
function raw(port, text) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => (buf += d));
    s.on('end', () => resolve(buf));
    s.on('error', () => resolve(buf));
    s.write(text);
    setTimeout(() => { s.destroy(); resolve(buf); }, 1500);
  });
}
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-'));

// startup errors
for (const [p, exp] of [['abc', 1], ['70000', 1], ['-1', 1], [' 80', 1], ['1e3', 1]]) {
  const r = await run({ PORT: p, DATA_FILE: path.join(tmp, 'x.json') }, tmp);
  check(`PORT=${p} exit1`, r.code === exp, JSON.stringify(r));
}
fs.writeFileSync(path.join(tmp, 'empty.json'), '');
fs.writeFileSync(path.join(tmp, 'bad.json'), '{"a":1}');
fs.writeFileSync(path.join(tmp, 'arr.json'), '[]');
fs.mkdirSync(path.join(tmp, 'dir.json'));
for (const f of ['empty.json', 'bad.json', 'arr.json', 'dir.json']) {
  const r = await run({ PORT: '0', DATA_FILE: f }, tmp);
  check(`DATA_FILE ${f}`, r.code === 1 && r.err === `cannot read data file ${f}\n`, JSON.stringify(r));
}
// PORT checked before data
{
  const r = await run({ PORT: 'x', DATA_FILE: 'empty.json' }, tmp);
  check('PORT before data', r.code === 1 && !r.err.includes('cannot read data file'), r.err);
}
// port in use
const blocker = net.createServer().listen(0, '127.0.0.1');
await new Promise((r) => blocker.on('listening', r));
{
  const r = await run({ PORT: String(blocker.address().port), DATA_FILE: 'n.json' }, tmp);
  check('port in use', r.code === 1 && r.err.split('\n').filter(Boolean).length === 1, JSON.stringify(r));
}
blocker.close();

// default data file in cwd
const cwd2 = fs.mkdtempSync(path.join(os.tmpdir(), 'probe2-'));
const s = await run({ PORT: '0' }, cwd2);
check('listening line', /^listening on http:\/\/127\.0\.0\.1:\d+\n$/.test(s.out), s.out);
const port = Number(s.out.match(/:(\d+)/)[1]);
const base = `http://127.0.0.1:${port}`;
const req = async (method, url, body, headers = {}) => {
  const r = await fetch(base + url, { method, body, headers });
  const t = await r.text();
  let j; try { j = JSON.parse(t); } catch { j = t; }
  return { s: r.status, j, ct: r.headers.get('content-type') };
};
const post = (obj, ct = 'application/json') => req('POST', '/api/bookings', typeof obj === 'string' ? obj : JSON.stringify(obj), ct ? { 'content-type': ct } : {});
check('no file at startup', !fs.existsSync(path.join(cwd2, 'bookings.json')));
let r = await req('GET', '/api/rooms');
check('rooms', r.s === 200 && JSON.stringify(r.j) === '{"rooms":["Aurora","Borealis","Cosmos"]}' && r.ct === 'application/json; charset=utf-8');
check('GET rooms no file', !fs.existsSync(path.join(cwd2, 'bookings.json')));
const good = { room: 'Aurora', title: '  Standup ', date: '2026-11-03', start: '09:00', end: '10:00' };
r = await post(good);
check('create', r.s === 201 && r.j.id === 1 && r.j.title === 'Standup' && Object.keys(r.j).length === 6, JSON.stringify(r));
check('file created in cwd', fs.existsSync(path.join(cwd2, 'bookings.json')));
r = await post({ ...good, start: '09:30', end: '09:45' });
check('409', r.s === 409 && r.j.error === 'room is already booked from 09:00 to 10:00', JSON.stringify(r));
r = await post({ ...good, start: '10:00', end: '11:00' });
check('adjacent ok', r.s === 201 && r.j.id === 2, JSON.stringify(r));
r = await post({ ...good, start: '08:00', end: '12:00' });
check('409 earliest', r.s === 409 && r.j.error === 'room is already booked from 09:00 to 10:00', JSON.stringify(r));
const cases = [
  [[good, 'text/plain'], 415, 'content type must be application/json'],
  [[good, null], 415, 'content type must be application/json'],
  [[good, ' \tApplication/JSON ; charset=x'], 201, null],
  [['x'.repeat(10001)], 413, 'body too large'],
  [['', 'text/plain'], 415, null],
  [['x'.repeat(10001), 'text/plain'], 415, null],
  [[''], 400, 'body must be a JSON object'],
  [['null'], 400, 'body must be a JSON object'],
  [['[]'], 400, 'body must be a JSON object'],
  [['﻿{}'], 400, 'body must be a JSON object'],
  [[{ ...good, room: 'aurora' }], 400, 'room must be one of Aurora, Borealis, Cosmos'],
  [[{ ...good, room: ['Aurora'] }], 400, 'room must be one of Aurora, Borealis, Cosmos'],
  [[{ ...good, title: '   ' }], 400, 'title must be 1 to 80 characters'],
  [[{ ...good, title: 'x'.repeat(81) }], 400, 'title must be 1 to 80 characters'],
  [[{ ...good, title: 5 }], 400, 'title must be 1 to 80 characters'],
  [[{ ...good, date: '2001-02-29' }], 400, 'date must be a valid YYYY-MM-DD date'],
  [[{ ...good, date: '2100-01-01' }], 400, 'date must be a valid YYYY-MM-DD date'],
  [[{ ...good, date: ' 2026-11-03' }], 400, 'date must be a valid YYYY-MM-DD date'],
  [[{ ...good, date: '٢٠٢٦-11-03' }], 400, 'date must be a valid YYYY-MM-DD date'],
  [[{ ...good, start: '9:00' }], 400, 'start must be HH:MM'],
  [[{ ...good, start: '24:00' }], 400, 'start must be HH:MM'],
  [[{ ...good, end: '10:60' }], 400, 'end must be HH:MM'],
  [[{ ...good, start: '11:00', end: '11:00' }], 400, 'end must be after start'],
  [['{"__proto__":{"room":"Aurora"}}'], 400, 'room must be one of Aurora, Borealis, Cosmos'],
];
for (const [[b, ct], st, msg] of cases) {
  r = await post(b, ct === undefined ? 'application/json' : ct);
  check(`post ${String(typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 40)} ct=${ct}`, r.s === st && (msg === null || r.j.error === msg), JSON.stringify(r).slice(0, 200));
}
r = await post({ ...good, date: '2000-02-29', title: 'x'.repeat(80) });
check('leap 2000 + 80 chars', r.s === 201, JSON.stringify(r));
r = await post({ ...good, title: '😀'.repeat(41), date: '2030-01-01' });
check('82 code units rejected', r.s === 400);

// listing
r = await req('GET', '/api/bookings');
check('list sorted', r.s === 200 && r.j.bookings.map((b) => b.id).join() === '4,1,2,3' , JSON.stringify(r.j));
for (const [q, st] of [['?date', 400], ['?date=', 400], ['?date=2026-11-03', 200], ['?date=2026-11-03&date=x', 200], ['?x=1', 200], ['?date=2026-02-30', 400], ['?date=%32026-11-03', 400], ['?date=2026%2D11-03', 200]]) {
  r = await req('GET', '/api/bookings' + q);
  check(`list ${q}`, r.s === st && (st !== 400 || r.j.error === 'date must be a valid YYYY-MM-DD date'), JSON.stringify(r).slice(0, 150));
}
// routing
const routes = [
  ['GET', '/api/%62ookings', 404, 'not found'], ['GET', '/api/./rooms', 404, 'not found'], ['GET', '/API/rooms', 404, 'not found'],
  ['GET', '/api/bookings/', 404, 'not found'], ['DELETE', '/api/bookings/', 404, 'not found'], ['DELETE', '/api/bookings/1/', 404, 'not found'],
  ['GET', '/api/bookings/abc', 405, 'method not allowed'], ['HEAD', '/api/rooms', 405, null], ['OPTIONS', '/api/bookings', 405, 'method not allowed'],
  ['PUT', '/', 405, 'method not allowed'], ['POST', '/app.js', 405, 'method not allowed'], ['DELETE', '/api/bookings/abc', 404, 'booking not found'],
  ['DELETE', '/api/bookings/01', 404, 'booking not found'], ['DELETE', '/api/bookings/99', 404, 'booking not found'], ['DELETE', '/api/bookings/1.0', 404, 'booking not found'],
  ['DELETE', '/api/bookings/%31', 404, 'booking not found'], ['GET', '/nope', 404, 'not found'], ['POST', '/nope', 404, 'not found'], ['GET', '/index.html', 404, 'not found'],
  ['GET', '/api/rooms?x=1', 200, null], ['DELETE', '/api/bookings/1?x', 204, null],
];
for (const [m, u, st, msg] of routes) {
  r = await req(m, u);
  check(`${m} ${u}`, r.s === st && (msg === null || r.j.error === msg), JSON.stringify(r).slice(0, 150));
}
r = await req('DELETE', '/api/bookings/1');
check('delete again 404', r.s === 404);
r = await req('GET', '/');
check('page ct', r.s === 200 && r.ct === 'text/html; charset=utf-8');
r = await req('GET', '/app.js');
check('js ct', r.s === 200 && r.ct === 'text/javascript; charset=utf-8');
// raw requests
let txt = await raw(port, 'GET /api/rooms HTTP/1.1\r\nHost: x\r\nContent-Length: 5\r\nConnection: close\r\n\r\nhello');
check('GET with body', txt.startsWith('HTTP/1.1 200'), txt.slice(0, 40));
txt = await raw(port, `POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: text/plain\r\nContent-Length: 200000\r\nConnection: close\r\n\r\n${'a'.repeat(200000)}`);
check('415 big body', txt.startsWith('HTTP/1.1 415'), txt.slice(0, 40));
txt = await raw(port, `POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n2710\r\n${'a'.repeat(10000)}\r\n1\r\nb\r\n0\r\n\r\n`);
check('413 chunked 10001', txt.startsWith('HTTP/1.1 413'), txt.slice(0, 40));
txt = await raw(port, `POST /api/bookings HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nContent-Length: 10000\r\nConnection: close\r\n\r\n{"room":1${' '.repeat(9991)}}`);
check('10000 ok-size', txt.includes('room must be'), txt.slice(0, 40));
// invalid utf8
{
  const b = Buffer.concat([Buffer.from('{"room":"Aurora","title":"'), Buffer.from([0xff]), Buffer.from('","date":"2027-01-01","start":"09:00","end":"10:00"}')]);
  const rr = await fetch(base + '/api/bookings', { method: 'POST', headers: { 'content-type': 'application/json' }, body: b });
  const j = await rr.json();
  check('invalid utf8 title', rr.status === 201 && j.title === '�', JSON.stringify(j));
}
// concurrency
const conc = await Promise.all(Array.from({ length: 20 }, (_, i) => post({ ...good, date: '2040-05-05', start: '09:00', end: `1${i % 10}:00`.slice(0, 5) })));
